import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int num = sc.nextInt();
        int den = sc.nextInt();
        int limit = sc.nextInt();
        int g = gcd(num, den);
        num /= g;
        den /= g;
        long x_curr = 0, y_curr = 1, x_best = 0, y_best = 1;
        double ratio = 1.0, tol = 1e-10;
        for (y_curr = 1; y_curr <= limit; y_curr++) {
            while (Math.abs(ratio * num / den - ratio * x_curr / y_curr) > Math.abs(ratio * num / den - ratio * (x_curr + 10000) / y_curr))
                x_curr += 10000;
            while (Math.abs(ratio * num / den - ratio * x_curr / y_curr) + tol > Math.abs(ratio * num / den - ratio * (x_curr + 1) / y_curr))
                x_curr++;
            if (Math.abs(ratio * num / den - ratio * x_curr / y_curr) < Math.abs(ratio * num / den - ratio * x_best / y_best)) {
                x_best = x_curr;
                y_best = y_curr;
            }
        }
        long resultX = Math.max(0, x_best - (den == 2 && x_best != num ? 1 : 0));
        System.out.println(resultX + "/" + y_best);
        sc.close();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

